struct npc_magma_giant : ScriptedAI
{
    npc_magma_giant(Creature* creature) : ScriptedAI(creature), summons(me)
    {
        introDone = false;
        number = 0;
    }

    EventMap events;
    SummonList summons;
    uint32 number;
    bool introDone;

    void Reset() override
    {
        events.Reset();
        DoCast(251888);
        me->RemoveAllAreaObjects();
        DespawnAllSummons();

        if (!introDone)
            me->SetFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1);
        else
            me->SetDisplayId(79099);
    }

    void JustReachedHome() override
    {
        if (introDone)
        {
            me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1);
            me->SetDisplayId(79099);
            DoCast(251896);
            events.RescheduleEvent(EVENT_3, 1000);
        }
    }

    void EnterCombat(Unit* /*who*/) override
    {
        events.RescheduleEvent(EVENT_1, 18000);
        events.RescheduleEvent(EVENT_2, 3000);
    }

    void JustDied(Unit* /*who*/) override
    {
        me->RemoveAllAreaObjects();
    }

    void EnterEvadeMode() override
    {
        ScriptedAI::EnterEvadeMode();
    }

    void JustSummoned(Creature* summon) override
    {
        summons.Summon(summon);

        summon->CastSpell(summon, 252735, true);
    }

    void StartEvent()
    {
        me->RemoveFlag(UNIT_FIELD_FLAGS, UNIT_FLAG_IMMUNE_TO_PC | UNIT_FLAG_IMMUNE_TO_NPC | UNIT_FLAG_NOT_ATTACKABLE_1);
        DoCast(252790);
        DoCast(251896);

        introDone = true;
        me->SetHomePosition(663.905f, 623.85f, 40.26792f, 0.0f);
        me->AddDelayedEvent(2000, [=]() -> void { me->GetMotionMaster()->MovePoint(1, 663.905f, 623.85f, 40.26792f); });
    }

    void MovementInform(uint32 type, uint32 data) override
    {
        if (type == POINT_MOTION_TYPE)
        {
            if (data == 1)
                events.RescheduleEvent(EVENT_3, 1000);
        }
    }

    void DoAction(int32 const action) override
    {
        switch (action)
        {
        case ACTION_1:
            number++;

            switch (number)
            {
            case 1:
                if (me->GetPositionX() >= 715.79f && me->GetPositionX() <= 729.79f)
                    StartEvent();
                break;
            case 2:
                if (me->GetPositionX() >= 730.9829f && me->GetPositionX() <= 735.9929f)
                    StartEvent();
                break;
            case 3:
                if (me->GetPositionX() >= 650.615f && me->GetPositionX() <= 657.635f)
                    StartEvent();
                break;
            case 4:
                if (me->GetPositionX() >= 589.9629f && me->GetPositionX() <= 595.9929f)
                    StartEvent();
                break;
            case 5:
                if (me->GetPositionX() >= 629.623f && me->GetPositionX() <= 635.653f)
                    StartEvent();
                break;
            }
        default:
            break;
        }
    }

    void DespawnAllSummons()
    {
        std::list<Creature*> list;
        list.clear();
        me->GetCreatureListWithEntryInGrid(list, 127356, 200.0f);
        if (!list.empty())
            for (auto& cre : list)
                cre->DespawnOrUnsummon(100);
    }

    void UpdateAI(uint32 diff) override
    {
        if (!UpdateVictim() && me->isInCombat())
            return;

        if (CheckHomeDistToEvade(diff, 150.0f))
            return;

        events.Update(diff);

        if (uint32 eventId = events.ExecuteEvent())
        {
            switch (eventId)
            {
            case EVENT_1:
                DoCast(252736);
                events.RescheduleEvent(EVENT_1, 20000);
                break;
            case EVENT_2:
                DoCast(252731);
                events.RescheduleEvent(EVENT_2, 6000);
                break;
            case EVENT_3:
                me->GetMotionMaster()->MoveRandom(15.0f);
                events.RescheduleEvent(EVENT_3, 7000);
                break;
            }
        }
        DoMeleeAttackIfReady();
    }
}

