                globalTimer = 35 * IN_MILLISECONDS;
                events.RescheduleEvent(EVENT_TOXIC_SPORES, 6 * IN_MILLISECONDS);
                events.RescheduleEvent(EVENT_CHAOTIC_SPHERE_NATURE, 35 * IN_MILLISECONDS);
