        instance->SendEncounterUnit(ENCOUNTER_FRAME_DISENGAGE, me);

        if (IsMythicRaid())
        {
            if (auto summoner = me->GetAnyOwner())
                summoner->GetAI()->DoAction(ACTION_2);
        }
    }

    void JustDied(Unit* killer) override
    {
        instance->SendEncounterUnit(ENCOUNTER_FRAME_DISENGAGE, me);
        summons.DespawnAll();

        if (IsMythicRaid())
            DoCast(me, SPELL_NATURE_INFUSION, true);
    }

