    {
        switch (spell->Id)
        {
            case SPELL_SUM_CHAOTIC_SPHERE_NATURE:
            {
                for (uint8 i = 0; i < 3; ++i)
                    me->SummonCreature(NPC_CHAOS_SPHERE, spherePos[i]);
                break;
            }
        }
    }

