                    DoCast(SPELL_SUM_CHAOTIC_SPHERE_NATURE);
                    events.RescheduleEvent(EVENT_CHAOTIC_SPHERE_NATURE, globalTimer);
                    break;
            }
        }
        DoMeleeAttackIfReady();
    }
